 internal sealed class CodeIndentation:DefaultIndentationStrategy {
  internal int Width=2;
  public override void IndentLine(TextDocument document,DocumentLine line){if(line.PreviousLine==null)return;string previous=document.GetText(line.PreviousLine);string prefix=new string(previous.TakeWhile(c=>c==' '||c=='\t').ToArray());string trim=previous.TrimEnd();if(trim.EndsWith(":" )||trim.EndsWith("{")||trim.EndsWith("["))prefix+=new string(' ',Width);string current=document.GetText(line);int whitespace=current.TakeWhile(c=>c==' '||c=='\t').Count();document.Replace(line.Offset,whitespace,prefix);}
 }
 internal sealed class IndentGuides:IBackgroundRenderer {
  readonly TextEditor editor;internal IndentGuides(TextEditor editor){this.editor=editor;}public KnownLayer Layer{get{return KnownLayer.Background;}}
  public void Draw(TextView view,DrawingContext dc){if(!view.VisualLinesValid)return;var pen=new Pen(FluentTheme.Muted,0.5){DashStyle=DashStyles.Dot};int step=editor.Options.IndentationSize;foreach(var line in view.VisualLines){string text=editor.Document.GetText(line.FirstDocumentLine);int spaces=text.TakeWhile(c=>c==' ').Count();for(int i=step;i<=Math.Min(spaces,80);i+=step){double x=i*view.WideSpaceWidth-view.HorizontalOffset;if(x<0||x>view.ActualWidth)continue;double y=line.VisualTop-view.VerticalOffset;dc.DrawLine(pen,new Point(x,y),new Point(x,y+line.Height));}}}
 }
