 internal sealed partial class CodeEditorWindow:Window {
  internal readonly TabControl Tabs=new TabControl();internal readonly List<EditorDocument> Documents=new List<EditorDocument>();readonly TextBlock status=CopyUi.Label("");readonly ComboBox indent=new ComboBox{Width=68,ItemsSource=new[]{"2","4","8"},SelectedIndex=0},encoding=new ComboBox{Width=140,ItemsSource=new[]{"UTF-8","UTF-8 BOM","UTF-16 LE","Windows-1250","Windows-1252",L.Text("codeEditor.original")},SelectedIndex=5},eol=new ComboBox{Width=90,ItemsSource=new[]{L.Text("codeEditor.original"),"CRLF","LF"},SelectedIndex=0};readonly TextBox find=new TextBox{Width=150},replace=new TextBox{Width=150};readonly WrapPanel replaceBar=new WrapPanel{Visibility=Visibility.Collapsed};readonly DispatcherTimer debounce=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(650)};int version;bool closing,closed;EditorDocument optionsDocument;internal Task LoadingTask,SaveTask,ValidationTask;internal EditorDocument Current{get{return Documents.FirstOrDefault(x=>x.Tab==Tabs.SelectedItem);}}
  internal CodeEditorWindow(Window owner){CopyUi.Style(this,owner,L.Text("codeEditor.title"),1200);Height=820;MinWidth=720;MinHeight=480;SizeToContent=SizeToContent.Manual;ResizeMode=ResizeMode.CanResize;DialogGeometry.Bound(this,1200,820,720,480);BuildEditorChrome();InitializeFormatControls();Tabs.SelectionChanged+=delegate(object sender,SelectionChangedEventArgs e){if(e.OriginalSource!=Tabs)return;SyncOptions();RefreshStatus();};debounce.Tick+=delegate{debounce.Stop();ValidationTask=Validate();};PreviewKeyDown+=delegate(object sender,KeyEventArgs e){if(e.Key==Key.F4&&Keyboard.Modifiers==ModifierKeys.Shift){e.Handled=true;External();return;}if(Keyboard.Modifiers==(ModifierKeys.Control|ModifierKeys.Shift)&&e.Key==Key.S){e.Handled=true;SaveTask=Save(true);return;}if(e.Key==Key.Escape&&replaceBar.Visibility==Visibility.Visible){replaceBar.Visibility=Visibility.Collapsed;e.Handled=true;return;}if(Keyboard.Modifiers==ModifierKeys.Control){if(e.Key==Key.S){e.Handled=true;SaveTask=Save(false);}else if(e.Key==Key.H){e.Handled=true;ShowReplace();}else if(e.Key==Key.O){e.Handled=true;OpenPicker();}else if(e.Key==Key.N){e.Handled=true;NewDocument();}else if(e.Key==Key.G){e.Handled=true;GoTo();}else if(e.Key==Key.W){e.Handled=true;CloseDocument(Current);}}};Closing+=async delegate(object sender,System.ComponentModel.CancelEventArgs e){if(closing||!HasUnsaved)return;e.Cancel=true;if(await PrepareClose()){var closeOperation=Dispatcher.BeginInvoke(new Action(Close));}};Closed+=delegate{closed=true;debounce.Stop();version++;foreach(var doc in Documents)if(doc.Location!=null)doc.Location.Dispose();};}
