  internal EditorDocument Add(EditorTextFile file){var editor=new TextEditor{Text=file.Text,ShowLineNumbers=true,FontFamily=new FontFamily("Consolas"),FontSize=14,Background=CompactTheme.WhiteSurface,Foreground=FluentTheme.Text,HorizontalScrollBarVisibility=ScrollBarVisibility.Auto,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};editor.WordWrap=wordWrap;editor.ShowLineNumbers=lineNumbers;editor.Options.ShowSpaces=editor.Options.ShowTabs=whitespace;editor.Options.ConvertTabsToSpaces=true;editor.Options.IndentationSize=2;var doc=new EditorDocument{File=file,Editor=editor,Caption=new TextBlock()};doc.Tab=new TabItem{Header=doc.Caption,Content=editor};editor.TextArea.IndentationStrategy=doc.Indentation;editor.TextArea.TextView.BackgroundRenderers.Add(new IndentGuides(editor));doc.Search=ICSharpCode.AvalonEdit.Search.SearchPanel.Install(editor);Highlight(doc);doc.Folding=FoldingManager.Install(editor.TextArea);editor.TextChanged+=delegate{doc.Caption.Text=DocumentName(doc)+(editor.IsModified||doc.FormatModified?" *":"");version++;debounce.Stop();debounce.Start();};editor.Document.UndoStack.PropertyChanged+=delegate{doc.Caption.Text=DocumentName(doc)+(editor.IsModified||doc.FormatModified?" *":"");};editor.TextArea.Caret.PositionChanged+=delegate{RefreshStatus();};Documents.Add(doc);Tabs.Items.Add(doc.Tab);doc.Caption.Text=DocumentName(doc);Tabs.SelectedItem=doc.Tab;editor.IsModified=false;editor.Focus();RefreshStatus();return doc;}
