  static void Highlight(EditorDocument doc){string ext=Path.GetExtension(SyntaxPath(doc)).ToLowerInvariant();doc.Editor.SyntaxHighlighting=HighlightingManager.Instance.GetDefinitionByExtension(ext);ScriptHighlight(doc,ext.ToLowerInvariant());if(ext==".json"||ext==".lng")doc.Editor.SyntaxHighlighting=HighlightingManager.Instance.GetDefinition("JavaScript");if(ext==".yml"||ext==".yaml"){const string yaml="<SyntaxDefinition xmlns='http://icsharpcode.net/sharpdevelop/syntaxdefinition/2008'><Color name='Comment' foreground='#6A9955'/><Color name='Key' foreground='#2879B0' fontWeight='bold'/><Color name='String' foreground='#A45D28'/><RuleSet><Span color='Comment' begin='#'/><Span color='String' begin='&quot;' end='&quot;'/><Span color='String' begin=\"'\" end=\"'\"/><Rule color='Key'>^[ ]*[A-Za-z_][A-Za-z0-9_.-]*(?=\\s*:)</Rule></RuleSet></SyntaxDefinition>";using(var xml=System.Xml.XmlReader.Create(new StringReader(yaml)))doc.Editor.SyntaxHighlighting=ICSharpCode.AvalonEdit.Highlighting.Xshd.HighlightingLoader.Load(xml,HighlightingManager.Instance);}}
