  internal async Task<bool> Save(bool saveAs){
   var doc=Current;if(doc==null||doc.Saving)return false;var file=doc.File;
   string text=doc.Editor.Text;if(doc.EolChoice>0)text=System.Text.RegularExpressions.Regex.Replace(text,"\r\n|\r|\n",doc.EolChoice==1?"\r\n":"\n");
   Encoding selected=file.Encoding;byte[] bom=file.Preamble;
   switch(doc.EncodingChoice){case 0:selected=new UTF8Encoding(false,true);bom=new byte[0];break;case 1:selected=new UTF8Encoding(true,true);bom=selected.GetPreamble();break;case 2:selected=new UnicodeEncoding(false,true,true);bom=selected.GetPreamble();break;case 3:case 4:selected=Encoding.GetEncoding(doc.EncodingChoice==3?1250:1252,EncoderFallback.ExceptionFallback,DecoderFallback.ExceptionFallback);bom=new byte[0];break;}
   doc.Saving=true;doc.Editor.IsReadOnly=true;
   try{
    if(doc.Location!=null&&doc.Location.Remote!=null){if(!await SaveRemote(doc,saveAs,text,selected,bom))return false;}
    else{
     string path=file.Path;if(saveAs||String.IsNullOrEmpty(path)){path=PickLocalPath(doc);if(String.IsNullOrEmpty(path))return false;}
     var baseline=path==file.Path?file:await Task.Run(()=>File.Exists(path)?EditorTextFile.Load(path):EditorTextFile.New());
     var target=new EditorTextFile{Path=path,Stamp=baseline.Stamp,Text=baseline.Text,Encoding=selected,Preamble=bom};await Task.Run(()=>target.Save(text));doc.File=target;
     if(doc.Location!=null&&doc.Location.Saved!=null)doc.Location.Saved();
    }
    if(doc.Editor.Text!=text)doc.Editor.Document.Replace(0,doc.Editor.Document.TextLength,text);
    doc.FormatModified=false;doc.Editor.IsModified=false;doc.Caption.Text=DocumentName(doc);Highlight(doc);if(Current==doc)SyncOptions();status.Text=L.Text("codeEditor.saved")+" / "+(doc.RemotePath??doc.File.Path);return true;
   }catch(Exception ex){status.Text=ex.Message;return false;}finally{doc.Saving=false;doc.Editor.IsReadOnly=false;}
  }
  internal bool HasUnsaved{get{return Documents.Any(x=>x.Editor.IsModified||x.FormatModified||x.Saving);}}
  bool askingClose;
  internal async Task<bool> PrepareClose(){if(askingClose||Documents.Any(x=>x.Saving))return false;askingClose=true;var discard=new List<EditorDocument>();try{foreach(var doc in Documents.ToArray()){if(!doc.Editor.IsModified&&!doc.FormatModified)continue;var answer=MessageBox.Show(this,L.Format("codeEditor.discard",DocumentName(doc)),L.Text("codeEditor.title"),MessageBoxButton.YesNoCancel,MessageBoxImage.Question,MessageBoxResult.Cancel);if(answer==MessageBoxResult.Cancel)return false;if(answer==MessageBoxResult.Yes){Tabs.SelectedItem=doc.Tab;if(!await Save(false))return false;}else discard.Add(doc);}foreach(var doc in discard){doc.FormatModified=false;doc.Editor.IsModified=false;}closing=true;return true;}finally{askingClose=false;}}
