  internal void FormatJson(){var doc=Current;if(doc==null)return;try{string nl=doc.Editor.Text.Contains("\r\n")?"\r\n":"\n";string formatted=JsonTextFormatter.Format(doc.Editor.Text,doc.Editor.Options.IndentationSize,nl);doc.Editor.Document.Replace(0,doc.Editor.Document.TextLength,formatted);status.Text=L.Text("codeEditor.valid");}catch(Exception ex){status.Text=ex.Message;}}
