  void UpdateFolding(EditorDocument doc){if(doc.Editor.Document.LineCount>20000)return;var folds=new List<NewFolding>();string ext=Path.GetExtension(SyntaxPath(doc)).ToLowerInvariant();if(ext==".yml"||ext==".yaml"){var stack=new Stack<Tuple<int,int>>();foreach(var line in doc.Editor.Document.Lines){string text=doc.Editor.Document.GetText(line);if(String.IsNullOrWhiteSpace(text)||text.TrimStart().StartsWith("#"))continue;int indent=text.TakeWhile(c=>c==' ').Count();while(stack.Count>0&&indent<=stack.Peek().Item2){var item=stack.Pop();if(line.Offset>item.Item1+1)folds.Add(new NewFolding(item.Item1,line.Offset-1));}if(text.TrimEnd().EndsWith(":"))stack.Push(Tuple.Create(line.EndOffset,indent));}while(stack.Count>0){var item=stack.Pop();if(doc.Editor.Document.TextLength>item.Item1)folds.Add(new NewFolding(item.Item1,doc.Editor.Document.TextLength));}}else if(ext==".json"||ext==".lng"){var stack=new Stack<int>();bool quote=false,escape=false;string text=doc.Editor.Text;for(int i=0;i<text.Length;i++){char c=text[i];if(quote){if(escape)escape=false;else if(c=='\\')escape=true;else if(c=='"')quote=false;continue;}if(c=='"')quote=true;else if(c=='{'||c=='[')stack.Push(i);else if((c=='}'||c==']')&&stack.Count>0){int start=stack.Pop();if(doc.Editor.Document.GetLineByOffset(start).LineNumber<doc.Editor.Document.GetLineByOffset(i).LineNumber)folds.Add(new NewFolding(start,i+1));}}}doc.Folding.UpdateFoldings(folds.OrderBy(x=>x.StartOffset),-1);}
