 public partial class MainWindow {
  CodeEditorWindow codeEditor;bool editorClosingHook,editorClosingForOwner;
  internal void OpenInternalEditor(string path){if(!editorClosingHook){editorClosingHook=true;Closing+=async delegate(object sender,System.ComponentModel.CancelEventArgs e){if(e.Cancel||codeEditor==null||!codeEditor.HasUnsaved)return;e.Cancel=true;if(editorClosingForOwner)return;editorClosingForOwner=true;try{var editor=codeEditor;if(await editor.PrepareClose()){editor.Close();var closeOperation=Dispatcher.BeginInvoke(new Action(Close));}}finally{editorClosingForOwner=false;}};}if(codeEditor==null){codeEditor=new CodeEditorWindow(this);codeEditor.Closed+=delegate{codeEditor=null;};codeEditor.Show();}codeEditor.Activate();if(path==null){var panel=active;codeEditor.NewDocument(new EditorSaveLocation{Folder=panel.CurrentPath,Remote=panel.IsRemote?panel.Remote.TransferConnection():null,Saved=delegate{if(panel.IsRemote)panel.Refresh();else RefreshPanels();}});}else{codeEditor.DefaultFolder=Path.GetDirectoryName(path);codeEditor.LoadingTask=codeEditor.OpenFile(path);}}
