  void EditExternalSelected(){if(RejectExtWrite())return;var entry=active.List.SelectedItem as Entry;if(entry==null||entry.IsDirectory||entry.IsParent)return;if(active.IsArchive){OpenArchiveFile(active,entry,true);return;}if(active.IsRemote){EditRemoteSelected();return;}try{var info=FileViewers.ExternalEditorInfo(entry.FullPath,ProgramSettings.Load());FileViewers.StartAssociatedEdit(info,start=>System.Diagnostics.Process.Start(start),this);}catch(Exception ex){MessageBox.Show(this,ex.Message,L.Text("editor.openFailed"));}}
